      "title": "Scaled agent adoption concentrates in bounded service operations",
      "type": "thesis",
      "path": "wiki/theses/Scaled agent adoption concentrates in bounded service operations.md",
      "summary": "The strongest current public evidence of scaled enterprise-agent use clusters in repetitive, high-volume service workflows with structured systems of record, limited action vocabularies, measurable service pain, and established exception paths. Comparable evidence of safe, broad cross-functional autonomy remains sparse.",
